def close(x, ref, rtol: float = 1e-8, atol: float = 1e-10) -> bool:
    a = np.asarray(x)
    r = np.asarray(ref)
    if a.shape != r.shape:
        print('shape', a.shape, r.shape)
        return False
    ok = True
    for u, v in zip(a.flat, r.flat):
        if abs(u - v) > atol + rtol * abs(v):
            print('mismatch', u, v)
            ok = False
    return ok

n = 30
A = sp.diags_array([np.full(n, 4.), np.full(n - 1, -1.), np.full(n - 1, -2.)], offsets=[0, 1, -1]).tocsr()
b = np.cos(np.arange(n) * 1.0)

class Counter:
    k: int
    def __init__(self):
        self.k = 0
    def __call__(self, x):
        self.k += 1

@test
def test_krylov():
    x, info = sl.qmr(A, b, rtol=1e-10)
    assert info == info_qmr and close(x, x_qmr)
    x, info = sl.tfqmr(A, b, rtol=1e-10)
    assert info == info_tfqmr and close(x, x_tfqmr)
    x, info = sl.lgmres(A, b, rtol=1e-10)
    assert info == info_lgmres and close(x, x_lgmres)
    x, info = sl.gcrotmk(A, b, rtol=1e-10)
    assert info == info_gcrotmk and close(x, x_gcrotmk)
    c1 = Counter(); sl.qmr(A, b, rtol=1e-10, callback=c1); assert c1.k == it_qmr
    c2 = Counter(); sl.tfqmr(A, b, rtol=1e-10, callback=c2); assert c2.k == it_tfqmr
    c3 = Counter(); sl.lgmres(A, b, rtol=1e-10, callback=c3); assert c3.k == it_lgmres
    c4 = Counter(); sl.gcrotmk(A, b, rtol=1e-10, callback=c4); assert c4.k == it_gcrotmk
    M = sp.diags_array([1. / np.full(n, 4.)], offsets=[0])
    assert close(sl.tfqmr(A, b, rtol=1e-10, M=M)[0], x_tfqmr_M)
    assert close(sl.lgmres(A, b, rtol=1e-10, M=M, inner_m=5, outer_k=2)[0], x_lgmres_M)
    assert close(sl.gcrotmk(A, b, rtol=1e-10, m=5, k=3)[0], x_gcrotmk_mk)
    x, info = sl.qmr(A, b, rtol=1e-10, maxiter=5)
    assert info == info_qmr5 and close(x, x_qmr5, 1e-10, 1e-12)
    x, info = sl.lgmres(A, b, rtol=1e-10, inner_m=4, maxiter=3)
    assert info == info_lgmres3 and close(x, x_lgmres3, 1e-10, 1e-12)
test_krylov()

@test
def test_expm():
    E = sp.csc_array(np.array([[0.1, 0.2, 0.], [0., -0.3, 0.1], [0.05, 0., 0.2]]))
    assert close(sl.expm(E).toarray(), expm_small, 1e-13, 1e-14)
    E2 = sp.csc_array(np.array([[1., 2., 0., 0.], [0., -1., 3., 0.], [0., 0., 0.5, 1.], [0., 0., 0., 2.]]))
    assert close(sl.expm(E2).toarray(), expm_upper, 1e-13, 1e-14)
    E3 = sp.csc_array(np.array(E3_d))
    assert close(sl.expm(E3).toarray(), expm_big, 1e-12, 1e-13)
    assert sl.expm(sp.csr_array(E)).format == "csr" and sl.expm(E).format == "csc"
test_expm()

@test
def test_onenormest():
    G = sp.csr_array(np.array(G_d))
    np.random.seed(7)
    assert abs(sl.onenormest(G) - one_est) < 1e-10
    np.random.seed(7)
    e, v, w = sl.onenormest(G, t=3, compute_v=True, compute_w=True)
    assert abs(e - one_est3) < 1e-10 and close(v, one_v3) and close(w, one_w3)
    assert sl.onenormest(sp.csr_array(np.eye(3) * 2.), t=3) == one_exact
test_onenormest()
